package com.mvt.backApp.user.service;
import com.mvt.backApp.common.security.*;import com.mvt.backApp.config.BootstrapProperties;import com.mvt.backApp.user.entity.*;import com.mvt.backApp.user.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class BootstrapService{private final BootstrapProperties properties;private final PermissionRepository permissionRepository;private final RoleRepository roleRepository;private final UserRepository userRepository;private final PasswordEncoder passwordEncoder;
 @Transactional public void initialize(){if(!properties.isEnabled())return;validate(properties.getSuperAdmin(),"super-admin");Role superAdmin=role(RoleNames.SUPER_ADMIN);superAdmin.setPermissions(resolve(PermissionNames.ALL));roleRepository.save(superAdmin);role(RoleNames.PATIENT);Role partner=role(RoleNames.CARE_PARTNER);partner.setPermissions(resolve(PermissionNames.DEFAULT_CARE_PARTNER));roleRepository.save(partner);Role admin=role(RoleNames.ADMIN);create(properties.getSuperAdmin(),superAdmin);if(properties.getAdmin().isEnabled()){validate(properties.getAdmin(),"admin");Set<String> requested=properties.getAdmin().getPermissions();if(requested==null||requested.isEmpty())requested=PermissionNames.DEFAULT_DELEGATED_ADMIN;if(!PermissionNames.ALL.containsAll(requested))throw new IllegalStateException("Unknown delegated-admin permissions");admin.setPermissions(resolve(requested));roleRepository.save(admin);create(properties.getAdmin(),admin);}}
 private Set<Permission> resolve(Collection<String> names){Set<Permission> r=new HashSet<>();names.forEach(n->r.add(permissionRepository.findByName(n).orElseGet(()->{Permission p=new Permission();p.setName(n);p.setActive(true);p.setDeleted(false);return permissionRepository.save(p);})));return r;}
 private Role role(String n){return roleRepository.findByName(n).orElseGet(()->{Role r=new Role();r.setName(n);r.setActive(true);r.setDeleted(false);return roleRepository.save(r);});}
 private void create(BootstrapProperties.Account a,Role r){String e=a.getEmail().trim().toLowerCase(Locale.ROOT);if(userRepository.existsByEmail(e))return;User u=new User();u.setEmail(e);u.setPasswordHash(passwordEncoder.encode(a.getPassword()));u.setFirstName(a.getFirstName().trim());u.setLastName(a.getLastName().trim());u.setGender(Gender.OTHER);u.setEmailVerified(true);u.setRole(r);u.setActive(true);u.setDeleted(false);userRepository.save(u);}
 private void validate(BootstrapProperties.Account a,String label){if(a.getEmail()==null||a.getPassword()==null||a.getFirstName()==null||a.getLastName()==null)throw new IllegalStateException("Bootstrap "+label+" values are required");if(a.getPassword().length()<12)throw new IllegalStateException("Bootstrap "+label+" password must have at least 12 characters");}}
